input.command:
cd /workspace
cat > /tmp/schema.sql <<'EOF'
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
.print === TRAZO3 SCHEMA ===
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') LIMIT 1;
.print === FACILITIES SCHEMA ===
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') LIMIT 1;
.print === CAR SCHEMA ===
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet') LIMIT 1;
EOF
timeout 180 duckdb < /tmp/schema.sql 2>&1 | head -120

cd /workspace
cat > /tmp/q234.sql <<'EOF'
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
.print === q02 tier counts (facilities) ===
SELECT tier, count(*) AS n FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') GROUP BY tier ORDER BY tier;
.print === q04 trazo3 rows + epsg ===
SELECT count(*) AS n_rows, 4326 AS epsg FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
.print === q03 CAR n_rows ===
SELECT count(*) AS n_rows FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet');
EOF
timeout 300 duckdb < /tmp/q234.sql 2>&1 | grep -v "^\[" | sed 's/\x1b\[[0-9;]*m//g'

cd /workspace
# Extract distinct listed ids to a file
awk -F, 'NR>1 && $1!="" {print $1}' lists/goias-sample.csv | sort -u > /tmp/ids.txt
echo "distinct listed ids: $(wc -l < /tmp/ids.txt)"
head -1 /tmp/ids.txt
cat > /tmp/q567.sql <<'EOF'
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
CREATE TEMP TABLE ids AS SELECT column0 AS cod_imovel FROM read_csv('/tmp/ids.txt', header=false);
CREATE TEMP TABLE car AS
  SELECT cod_imovel, num_area, municipio, cod_estado
  FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
  WHERE cod_imovel IN (SELECT cod_imovel FROM ids);
.print === id rows in CAR: distinct matched ids and total CAR rows ===
SELECT count(DISTINCT cod_imovel) AS matched_distinct_ids, count(*) AS car_rows FROM car;
.print === listed ids NOT found in CAR ===
SELECT count(*) AS missing_ids FROM ids WHERE cod_imovel NOT IN (SELECT DISTINCT cod_imovel FROM car);
.print === q07a: listed ids with >1 CAR row ===
SELECT count(*) AS n_duplicate_ids FROM (SELECT cod_imovel FROM car GROUP BY cod_imovel HAVING count(*)>1);
.print === q07b: matched id-parcels with num_area < 1 (distinct id) ===
SELECT count(DISTINCT cod_imovel) AS n_parcels_under_1ha FROM car WHERE num_area < 1;
.print === q06: distinct id-parcels per municipio (CAR municipio) ===
SELECT municipio, count(DISTINCT cod_imovel) AS n_parcels FROM car GROUP BY municipio ORDER BY n_parcels DESC, municipio;
EOF
timeout 900 duckdb < /tmp/q567.sql 2>&1 | grep -v "^\[" | sed 's/\x1b\[[0-9;]*m//g'

cd /workspace
cat > /tmp/geores.sql <<'EOF'
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
CREATE TEMP TABLE g AS SELECT gid, ST_GeomFromText(wkt) AS geom FROM read_csv('/tmp/geoms.csv', header=true);
CREATE TEMP TABLE gbb AS SELECT min(ST_XMin(geom)) x0, max(ST_XMax(geom)) x1, min(ST_YMin(geom)) y0, max(ST_YMax(geom)) y1 FROM g;
CREATE TEMP TABLE car AS
  SELECT cod_imovel, num_area, municipio, geometry AS geom
  FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
  WHERE cod_estado='GO'
    AND bbox.xmin <= (SELECT x1 FROM gbb) AND bbox.xmax >= (SELECT x0 FROM gbb)
    AND bbox.ymin <= (SELECT y1 FROM gbb) AND bbox.ymax >= (SELECT y0 FROM gbb);
.print === candidate CAR parcels in region ===
SELECT count(*) FROM car;
.print === best-overlap parcel per geometry ===
WITH j AS (
  SELECT g.gid, c.cod_imovel, c.municipio,
         ST_Area(ST_Intersection(g.geom, c.geom)) AS ia
  FROM g JOIN car c ON ST_Intersects(g.geom, c.geom)
), r AS (
  SELECT gid, cod_imovel, municipio, ia,
         row_number() OVER (PARTITION BY gid ORDER BY ia DESC) rn
  FROM j
)
SELECT gid, cod_imovel, municipio, ia FROM r WHERE rn=1 ORDER BY gid;
EOF
timeout 900 duckdb < /tmp/geores.sql 2>&1 | grep -v "^\[" | sed 's/\x1b\[[0-9;]*m//g'

cd /workspace
cat > /tmp/q08b.sql <<'EOF'
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
CREATE TEMP TABLE env AS SELECT ST_MakeEnvelope(-51.51685499999999,-15.97435111,-51.20062249999998,-15.481647166112458) AS geom,
  -51.51685499999999 x0, -51.20062249999998 x1, -15.97435111 y0, -15.481647166112458 y1;
SELECT count(*) AS n_fields_in_envelope
FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') f, env
WHERE f.bbox.xmin <= env.x1 AND f.bbox.xmax >= env.x0
  AND f.bbox.ymin <= env.y1 AND f.bbox.ymax >= env.y0
  AND ST_Intersects(f.geometry, env.geom);
EOF
timeout 900 duckdb < /tmp/q08b.sql 2>&1 | grep -v "^\[" | sed 's/\x1b\[[0-9;]*m//g'
